def Strongest_Extension(class_name, extensions):
    def strength(extension):
        cap = sum(1 for c in extension if c.isupper())
        sm = sum(1 for c in extension if c.islower())
        return cap - sm

    strongest_extension_name = extensions[0]
    max_strength = strength(strongest_extension_name)

    for current_extension in extensions[1:]:
        current_strength = strength(current_extension)
        if current_strength > max_strength:
            strongest_extension_name = current_extension
            max_strength = current_strength

    return f"{class_name}.{strongest_extension_name}"

