// Helper function to calculate the strength of an extension
function method strength(extension: string): int
    returns (s: int)
{
    var cap := 0;
    var sm := 0;

    var i := 0;
    while i < extension.Length
        invariant 0 <= i <= extension.Length
        invariant cap == CountUppercase(extension, 0, i) && sm == CountLowercase(extension, 0, i)
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            cap := cap + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            sm := sm + 1;
        }
        i := i + 1;
    }

    s := cap - sm;
}

// Helper functions to count uppercase and lowercase letters
function method CountUppercase(s: string, start: int, end: int): int
    requires 0 <= start <= end <= s.Length
    ensures 0 <= CountUppercase(s, start, end) <= end - start
{
    if start == end {
        return 0;
    }
    return (if s[start] >= 'A' && s[start] <= 'Z' then 1 else 0) + CountUppercase(s, start + 1, end);
}

